/* board.c - pin table and low level drivers of the reaction game.
 *
 * The *_Pin / *_GPIO_Port names below come from main.h. CubeMX generates
 * them from the "User Label" you give each pin (see docs/PINOUT.md). */

#include "board.h"
#include "main.h"

/* Handles generated by CubeMX */
extern ADC_HandleTypeDef  hadc1;   /* 2 pots, scan + DMA circular */
extern SPI_HandleTypeDef  hspi1;   /* TX only: 2 x 74HC595 */
extern TIM_HandleTypeDef  htim2;   /* free-running 32 bit, 1 MHz */
extern TIM_HandleTypeDef  htim4;   /* PWM channel 1 -> buzzer */

#define BUZZER_TIM_CLK_HZ   1000000U   /* TIM4 after prescaler 83 (84 MHz / 84) */
#define DEBOUNCE_US         30000U     /* ignore edges 30 ms after an accepted one */
#define SEG_COMMON_ANODE    0          /* 1 if the displays are common anode */

/* ------------------------------------------------------------------ */
/* Pin tables                                                         */
/* ------------------------------------------------------------------ */
typedef struct {
    GPIO_TypeDef *port;
    uint16_t      pin;
} Pin_t;

/* Cue LEDs, indexed [player][input type] */
static const Pin_t led_pin[PLAYER_COUNT][INPUT_COUNT] = {
    [PLAYER_1] = { [INPUT_BUTTON] = { LED_BTN_P1_GPIO_Port, LED_BTN_P1_Pin },
                   [INPUT_SWITCH] = { LED_SW_P1_GPIO_Port,  LED_SW_P1_Pin  },
                   [INPUT_POT]    = { LED_POT_P1_GPIO_Port, LED_POT_P1_Pin } },
    [PLAYER_2] = { [INPUT_BUTTON] = { LED_BTN_P2_GPIO_Port, LED_BTN_P2_Pin },
                   [INPUT_SWITCH] = { LED_SW_P2_GPIO_Port,  LED_SW_P2_Pin  },
                   [INPUT_POT]    = { LED_POT_P2_GPIO_Port, LED_POT_P2_Pin } },
};

/* EXTI inputs: which pin is which player/input */
typedef struct {
    uint16_t    pin;
    Player_t    player;
    InputType_t input;
    uint32_t    last_us;      /* time of the last accepted edge */
} ExtiInput_t;

static ExtiInput_t exti_input[] = {
    { BTN_P1_Pin, PLAYER_1, INPUT_BUTTON, 0U },
    { SW_P1_Pin,  PLAYER_1, INPUT_SWITCH, 0U },
    { BTN_P2_Pin, PLAYER_2, INPUT_BUTTON, 0U },
    { SW_P2_Pin,  PLAYER_2, INPUT_SWITCH, 0U },
};
#define EXTI_INPUT_COUNT  (sizeof exti_input / sizeof exti_input[0])

/* ------------------------------------------------------------------ */
/* State                                                              */
/* ------------------------------------------------------------------ */
static osMessageQueueId_t input_queue[PLAYER_COUNT];   /* one per player */
static osSemaphoreId_t    start_sem   = NULL;          /* released by B1 */
static uint32_t           b1_last_us  = 0U;
static osMutexId_t        spi_mutex   = NULL;
static volatile uint16_t  adc_raw[PLAYER_COUNT];   /* [0] = A0 (P1), [1] = A1 (P2) */

/* 7-segment patterns, bit0 = a ... bit6 = g, bit7 = dp (595 outputs QA..QH) */
static const uint8_t seg_digit[10] = {
    0x3F, 0x06, 0x5B, 0x4F, 0x66, 0x6D, 0x7D, 0x07, 0x7F, 0x6F
};

/* ------------------------------------------------------------------ */
/* Init                                                               */
/* ------------------------------------------------------------------ */
void Board_Init(const osMessageQueueId_t inputQueues[PLAYER_COUNT])
{
    for (int p = 0; p < PLAYER_COUNT; p++) {
        input_queue[p] = inputQueues[p];
    }
    spi_mutex = osMutexNew(NULL);
    start_sem = osSemaphoreNew(1U, 0U, NULL);      /* binary, starts empty */
    if ((spi_mutex == NULL) || (start_sem == NULL)) {
        Error_Handler();
    }

    HAL_TIM_Base_Start(&htim2);                          /* timestamps */
    HAL_TIM_PWM_Start(&htim4, TIM_CHANNEL_1);            /* buzzer, silent */
    __HAL_TIM_SET_COMPARE(&htim4, TIM_CHANNEL_1, 0U);
    if (HAL_ADC_Start_DMA(&hadc1, (uint32_t *)adc_raw, PLAYER_COUNT) != HAL_OK) {
        Error_Handler();
    }
    /* The DMA keeps adc_raw up to date by itself. Its interrupt would fire
     * about 200 000 times per second (continuous scan, 2 samples), so switch
     * it off in the NVIC; the transfers do not need it. */
    HAL_NVIC_DisableIRQ(DMA2_Stream0_IRQn);

    Board_LedsAllOff();
    Board_DisplayScores(0U, 0U);
}

uint32_t Board_NowUs(void)
{
    return __HAL_TIM_GET_COUNTER(&htim2);
}

bool Board_WaitStartButton(uint32_t timeout_ticks)
{
    return (osSemaphoreAcquire(start_sem, timeout_ticks) == osOK);
}

/* ------------------------------------------------------------------ */
/* LEDs, pots                                                         */
/* ------------------------------------------------------------------ */
void Board_LedSet(Player_t player, InputType_t input, bool on)
{
    const Pin_t *p = &led_pin[player][input];
    HAL_GPIO_WritePin(p->port, p->pin, on ? GPIO_PIN_SET : GPIO_PIN_RESET);
}

void Board_LedsAllOff(void)
{
    for (int pl = 0; pl < PLAYER_COUNT; pl++) {
        for (int in = 0; in < INPUT_COUNT; in++) {
            Board_LedSet((Player_t)pl, (InputType_t)in, false);
        }
    }
}

uint16_t Board_PotRead(Player_t player)
{
    return adc_raw[player];
}

/* ------------------------------------------------------------------ */
/* 7-segment displays on two daisy-chained 74HC595                    */
/* ------------------------------------------------------------------ */
static uint8_t prvSegments(uint8_t digit)
{
    uint8_t v = seg_digit[(digit > 9U) ? 9U : digit];
#if SEG_COMMON_ANODE
    v = (uint8_t)~v;
#endif
    return v;
}

void Board_DisplayScores(uint8_t scoreP1, uint8_t scoreP2)
{
    /* The first byte shifted out ends up in the LAST chip of the chain.
     * Chip 1 (MOSI side, right on the breadboard) = player 2,
     * chip 2 (chained to Q7', left on the breadboard) = player 1. */
    uint8_t frame[2] = { prvSegments(scoreP1), prvSegments(scoreP2) };

    osMutexAcquire(spi_mutex, osWaitForever);
    HAL_SPI_Transmit(&hspi1, frame, 2U, 10U);
    HAL_GPIO_WritePin(LATCH_595_GPIO_Port, LATCH_595_Pin, GPIO_PIN_SET);   /* outputs update */
    HAL_GPIO_WritePin(LATCH_595_GPIO_Port, LATCH_595_Pin, GPIO_PIN_RESET);
    osMutexRelease(spi_mutex);
}

/* ------------------------------------------------------------------ */
/* Buzzer                                                             */
/* ------------------------------------------------------------------ */
void Board_BuzzerTone(uint32_t freq_hz)
{
    if (freq_hz == 0U) {
        __HAL_TIM_SET_COMPARE(&htim4, TIM_CHANNEL_1, 0U);
        return;
    }
    uint32_t arr = (BUZZER_TIM_CLK_HZ / freq_hz) - 1U;
    __HAL_TIM_SET_AUTORELOAD(&htim4, arr);
    __HAL_TIM_SET_COMPARE(&htim4, TIM_CHANNEL_1, (arr + 1U) / 2U);   /* 50 % duty */
}

/* ------------------------------------------------------------------ */
/* Button / switch edges (runs in the EXTI interrupt)                 */
/* ------------------------------------------------------------------ */
void HAL_GPIO_EXTI_Callback(uint16_t GPIO_Pin)
{
    uint32_t now = Board_NowUs();      /* timestamp first, as early as possible */

    if (GPIO_Pin == B1_Pin) {          /* blue button: start / restart */
        if ((b1_last_us == 0U) || ((now - b1_last_us) >= DEBOUNCE_US)) {
            b1_last_us = now;
            (void)osSemaphoreRelease(start_sem);   /* fails harmlessly if already pending */
        }
        return;
    }

    for (uint32_t i = 0; i < EXTI_INPUT_COUNT; i++) {
        ExtiInput_t *in = &exti_input[i];
        if (in->pin != GPIO_Pin) {
            continue;
        }
        if ((now - in->last_us) < DEBOUNCE_US && in->last_us != 0U) {
            return;                    /* contact bounce */
        }
        in->last_us = now;

        InputEvent_t evt = { in->player, in->input, now };
        if (input_queue[in->player] != NULL) {
            (void)osMessageQueuePut(input_queue[in->player], &evt, 0U, 0U);   /* timeout 0 in ISR */
        }
        return;
    }
}
